'use strict';
(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.ReikaBehaviorBridge=api;})(typeof globalThis!=='undefined'?globalThis:this,function(){
function mount(){const behavior=window.ReikaBehavior,interaction=window.ReikaInteractionController,host=document.querySelector('.reika-interaction');if(!behavior||!interaction||!host)return;
const state=behavior.create();const element=document.createElement('div');element.className='reika-behavior-v116';element.innerHTML='<h4>Эмоциональные хвосты · v99–v116</h4><label><input id="behaviorSync" type="checkbox" checked> Синхронизировать хвосты и эмоции</label><label for="behaviorIntensity">Сила реакции (%)</label><input id="behaviorIntensity" type="range" min="0" max="100" value="65"><button id="behaviorReset" type="button">Сбросить движение хвостов</button><p id="behaviorStatus" role="status" aria-live="polite">Локальная анимация по эмоциям; не физический Live2D-риг.</p>';host.append(element);
const sync=element.querySelector('#behaviorSync'),intensity=element.querySelector('#behaviorIntensity'),status=element.querySelector('#behaviorStatus');let last=performance.now(),current={amplitude:4,frequency:.45},raf=0;const reduced=window.matchMedia('(prefers-reduced-motion: reduce)');
function update(){const mood=interaction.currentMood(document.getElementById('mood')?.value||'neutral');state.set(mood);const now=performance.now(),dt=Math.min(Math.max(0,(now-last)/1000),.1);last=now;current=state.step(dt);const motion=window.ReikaTailMotionController;if(motion?.setReactive){const factor=sync.checked&&!reduced.matches?Number(intensity.value)/100:0;motion.setReactive({amplitude:current.amplitude*factor,frequency:current.frequency});}raf=requestAnimationFrame(update);}
window.addEventListener('reika:reply',()=>{status.textContent='Реакция хвостов: '+interaction.currentMood('neutral')+' · локальные правила.';});
element.querySelector('#behaviorReset').onclick=()=>{state.reset();const motion=window.ReikaTailMotionController;if(motion?.setReactive)motion.setReactive(null);sync.checked=false;status.textContent='Связь хвостов и эмоций выключена.';};
raf=requestAnimationFrame(update);window.addEventListener('pagehide',()=>cancelAnimationFrame(raf),{once:true});return {get enabled(){return sync.checked;},get profile(){return {...current};}};}
return {mount};
});
if(typeof window!=='undefined')window.ReikaBehaviorBridgeController=window.ReikaBehaviorBridge.mount();
